//----------------------------------------------------------------------------------------CListenerThread::~CListenerThread(){}//----------------------------------------------------------------------------------------// Listen//----------------------------------------------------------------------------------------//----------------------------------------------------------------------------------------// Run//----------------------------------------------------------------------------------------void CListenerThread::Run(){	fEndpoint.Open("tilisten,tcp");	{		OSStatus junk = fEndpoint.SetOption(IP_REUSEADDR, true);		Assertion_AC(junk == noErr, "Unable to negotiate raw mode for listener endpoint");	}	fEndpoint.Bind(fLocalAddress);	for (;;)	{		CInetAddress remoteIPAddress;		CCall call(remoteIPAddress);		OSStatus listenErr = fEndpoint.GetOTEndpoint()->Listen(&call);		if (listenErr)			break;		HandleConnection(remoteIPAddress, call);	}	fEndpoint.Close();}//----------------------------------------------------------------------------------------// HandleConnection//----------------------------------------------------------------------------------------void CListenerThread::HandleConnection(const InetAddress& remoteIPAddress, TCall& call){	bool accepted = false;	if (WillAccept(remoteIPAddress))	{		CAutoPtr_AC<CServerThread> server = DoMakeServerThread();		if (server)		{			EndpointRef worker = server->DoMakeEndpoint(fEndpoint.GetYielder(), fEndpoint.GetProgress());			if (worker)			{				ThrowIfOSStatus(fEndpoint.GetOTEndpoint()->Accept(worker, &call));				StartServer(server.release());				accepted = true;			}		}	}	if (!accepted)		Reject(call);}//----------------------------------------------------------------------------------------// WillAccept//----------------------------------------------------------------------------------------bool CListenerThread::WillAccept(const InetAddress& /*remoteIPAddress*/){	return true;}//----------------------------------------------------------------------------------------// Reject//----------------------------------------------------------------------------------------void CListenerThread::Reject(TCall& call){	OSStatus junk = fEndpoint.GetOTEndpoint()->SndDisconnect(&call);}//----------------------------------------------------------------------------------------// DoMakeServerThread//----------------------------------------------------------------------------------------CServerThread* CListenerThread::DoMakeServerThread(){	return TH_new CServerThread();}//----------------------------------------------------------------------------------------// StartServer//----------------------------------------------------------------------------------------void CListenerThread::StartServer(CServerThread* server){	server->Start();}//----------------------------------------------------------------------------------------// End of CListenerThread.cpp